    {
        return _options;
    };
}

function scr_shortcut(arg0, arg1, arg2 = -1, arg3 = -1) constructor
{
    _label = arg0;
    _room_index = arg1;
    _flag_id = arg2;
    _flag_value = arg3;

    is_optional = function()
    {
        return _flag_id != -1;
    };

    is_unlocked = function()
    {
        if (is_optional())
        {
            return scr_flag_get_ext(_flag_id, _flag_value) == 1;
        }
        return true;
    };

    get_label = function()
    {
        return _label;
    };

    get_room_index = function()
    {
        return _room_index;
    };
}

